  padding: 12px;
  border: 1px solid #8885;
  border-radius: 8px;
}
.ref-options-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 12px 0;
}
.ref-option-group {
  min-width: 0;
  padding: 12px;
  border: 1px solid #8885;
  border-radius: 8px;
}
.ref-option-group label {
  margin-top: 0;
  font-weight: 600;
}
.ref-option-group p {
  min-height: 2.8em;
  margin: 6px 0 10px;
}
.reference-library .ref-toolbar {
  flex-wrap: wrap;
  align-items: center;
}
.reference-library .ref-toolbar select {
  flex: 1 1 180px;
}

.reference-library label {
  display: block;
  margin: 10px 0;
